import re
from typing import List

_TOKEN_RE = re.compile(r'\s+|\*\*|[+\-*/()]|\d+\.?\d*|\.\d+')

def _tokenize(expr: str) -> List[str]:
    tokens = _TOKEN_RE.findall(expr)
    if ''.join(tokens).replace(' ', '') != expr.replace(' ', ''):
        raise ValueError(f"Invalid character in expression: {expr!r}")
    return [t for t in tokens if not t.isspace()]

class _Parser:
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def _peek(self) -> str | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self) -> str:
        tok = self._peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        self.pos += 1
        return tok

    def parse(self) -> float:
        res = self._expr()
        if self._peek() is not None:
            raise ValueError(f"Unexpected token: {self._peek()!r}")
        return res

    def _expr(self) -> float:
        res = self._term()
        while self._peek() in ('+', '-'):
            op = self._consume()
            right = self._term()
            res = res + right if op == '+' else res - right
        return res

    def _term(self) -> float:
        res = self._factor()
        while self._peek() in ('*', '/'):
            op = self._consume()
            right = self._factor()
            if op == '/':
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                res = res / right
            else:
                res = res * right
        return res

    def _factor(self) -> float:
        if self._peek() in ('-', '+'):
            op = self._consume()
            val = self._factor()
            return -val if op == '-' else val
        return self._power()

    def _power(self) -> float:
        base = self._atom()
        if self._peek() == '**':
            self._consume()
            exp = self._factor()  # Right-associative via mutual recursion
            return base ** exp
        return base

    def _atom(self) -> float:
        tok = self._peek()
        if tok == '(':
            self._consume()
            res = self._expr()
            if self._consume() != ')':
                raise ValueError("Unbalanced parentheses")
            return res
        if tok is None:
            raise ValueError("Unexpected end of expression")
        self._consume()
        try:
            return float(tok)
        except ValueError:
            raise ValueError(f"Invalid number: {tok!r}")

def evaluate(expression: str) -> float:
    return _Parser(_tokenize(expression)).parse()

# Usage Examples
if __name__ == "__main__":
    print(evaluate("2 + 3 * 4"))          # Precedence: 14.0
    print(evaluate("(2 + 3) * 4"))        # Parentheses: 20.0
    print(evaluate("-2 ** 2"))            # Unary minus: -4.0

from enum import Enum, auto
from typing import List, Union

class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    TIMES = auto()
    DIVIDE = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    __slots__ = ('type', 'value', 'lexeme')
    def __init__(self, type: TokenType, value: Union[float, None] = None, lexeme: str = ''):
        self.type = type
        self.value = value
        self.lexeme = lexeme

class ParseError(Exception):
    pass

class EvaluationError(Exception):
    pass

def tokenize(expr: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit() or ch == '.':
            start = i
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                i += 1
            num_str = expr[start:i]
            if num_str.count('.') > 1:
                raise ParseError(f"Invalid number literal: '{num_str}' at position {start}")
            value = float(num_str) if '.' in num_str else int(num_str)
            tokens.append(Token(TokenType.NUMBER, value, num_str))
            continue
        if ch == '+':
            tokens.append(Token(TokenType.PLUS, lexeme='+'))
            i += 1
        elif ch == '-':
            tokens.append(Token(TokenType.MINUS, lexeme='-'))
            i += 1
        elif ch == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(Token(TokenType.POWER, lexeme='**'))
                i += 2
            else:
                tokens.append(Token(TokenType.TIMES, lexeme='*'))
                i += 1
        elif ch == '/':
            tokens.append(Token(TokenType.DIVIDE, lexeme='/'))
            i += 1
        elif ch == '(':
            tokens.append(Token(TokenType.LPAREN, lexeme='('))
            i += 1
        elif ch == ')':
            tokens.append(Token(TokenType.RPAREN, lexeme=')'))
            i += 1
        else:
            raise ParseError(f"Unexpected character '{ch}' at position {i}")
    tokens.append(Token(TokenType.EOF))
    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: TokenType = None) -> Token:
        tok = self.peek()
        if expected_type is not None and tok.type != expected_type:
            raise ParseError(f"Expected {expected_type.name}, got {tok.type.name} ('{tok.lexeme}') at position {self.pos}")
        self.pos += 1
        return tok

    def parse_expression(self) -> float:
        left = self.parse_term()
        while self.peek().type in (TokenType.PLUS, TokenType.MINUS):
            op = self.consume()
            right = self.parse_term()
            if op.type == TokenType.PLUS:
                left += right
            else:
                left -= right
        return left

    def parse_term(self) -> float:
        left = self.parse_factor()
        while self.peek().type in (TokenType.TIMES, TokenType.DIVIDE):
            op = self.consume()
            right = self.parse_factor()
            if op.type == TokenType.TIMES:
                left *= right
            else:
                if right == 0.0:
                    raise EvaluationError("Division by zero")
                left /= right
        return left

    def parse_factor(self) -> float:
        if self.peek().type == TokenType.MINUS:
            self.consume()
            return -self.parse_factor()
        left = self.parse_primary()
        while self.peek().type == TokenType.POWER:
            self.consume()
            right = self.parse_factor()  # right-associative
            left **= right
        return left

    def parse_primary(self) -> float:
        tok = self.peek()
        if tok.type == TokenType.LPAREN:
            self.consume()
            expr = self.parse_expression()
            self.consume(TokenType.RPAREN)
            return expr
        elif tok.type == TokenType.NUMBER:
            self.consume()
            return float(tok.value)  # ensure float
        else:
            raise ParseError(f"Unexpected token {tok.type.name} ('{tok.lexeme}') at position {self.pos}")

def evaluate(expression: str) -> float:
    tokens = tokenize(expression)
    parser = Parser(tokens)
    result = parser.parse_expression()
    if parser.peek().type != TokenType.EOF:
        raise ParseError(f"Unexpected token after expression: '{parser.peek().lexeme}'")
    return result

# Usage examples
if __name__ == "__main__":
    # Example 1: Precedence
    print(evaluate("3 + 4 * 2"))          # 11.0
    # Example 2: Parentheses
    print(evaluate("(3 + 4) * 2"))        # 14.0
    # Example 3: Unary minus and power
    print(evaluate("-2**3"))              # -8.0
    print(evaluate("2**-3"))              # 0.125
    print(evaluate("-2**-3"))             # -0.125

import re
from typing import List, Tuple, Optional, Union

class ParseError(Exception):
    pass

class Token:
    def __init__(self, type: str, value: Union[str, float, int]):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value})"

def tokenize(expr: str) -> List[Token]:
    token_spec = [
        ('NUMBER', r'\d+(\.\d*)?'),
        ('OP', r'\*\*|[+\-*/()]'),
        ('SKIP', r'\s+'),
        ('MISMATCH', r'.')
    ]
    tokens = []
    pos = 0
    while pos < len(expr):
        match = None
        for tok_type, pattern in token_spec:
            regex = re.compile(pattern)
            match = regex.match(expr, pos)
            if match:
                text = match.group(0)
                if tok_type == 'NUMBER':
                    tokens.append(Token('NUMBER', float(text) if '.' in text else int(text)))
                elif tok_type == 'OP':
                    tokens.append(Token('OP', text))
                elif tok_type == 'SKIP':
                    pass
                else:
                    raise ParseError(f"Unexpected character: {text}")
                pos = match.end()
                break
        if not match:
            raise ParseError(f"Tokenization failed at position {pos}")
    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected: Optional[str] = None) -> Token:
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")
        if expected and token.type != 'OP' or token.value != expected:
            raise ParseError(f"Expected '{expected}', got {token.value}")
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self.expr()
        if self.peek() is not None:
            raise ParseError("Unexpected token at end of expression")
        return result

    def expr(self) -> float:
        left = self.term()
        while self.peek() and self.peek().value in ('+', '-'):
            op = self.consume().value
            right = self.term()
            left = left + right if op == '+' else left - right
        return left

    def term(self) -> float:
        left = self.factor()
        while self.peek() and self.peek().value in ('*', '/'):
            op = self.consume().value
            right = self.factor()
            if op == '/' and right == 0:
                raise ParseError("Division by zero")
            left = left * right if op == '*' else left / right
        return left

    def factor(self) -> float:
        if self.peek() and self.peek().value == '-':
            self.consume('-')
            return -self.power()
        return self.power()

    def power(self) -> float:
        left = self.atom()
        if self.peek() and self.peek().value == '**':
            self.consume('**')
            right = self.factor()
            return left ** right
        return left

    def atom(self) -> float:
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")

        if token.type == 'NUMBER':
            self.pos += 1
            return float(token.value)
        elif token.value == '(':
            self.consume('(')
            result = self.expr()
            self.consume(')')
            return result
        raise ParseError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    tokens = tokenize(expression)
    parser = Parser(tokens)
    return parser.parse()

# Usage examples
if __name__ == "__main__":
    # Example 1: Precedence
    print(evaluate("2 + 3 * 4 ** 2"))  # 2 + 3 * (4^2) = 2 + 3*16 = 50

    # Example 2: Parentheses and unary minus
