import re
from typing import List, Iterator

def evaluate(expression: str) -> float:
    """
    Parses and evaluates an arithmetic expression.
    Precedence: ** (right) > unary - > * / > + -
    """
    tokens = _tokenize(expression)
    result = _Parser(tokens).parse_expression()

    if not _Parser.current_token(tokens) is None:
        raise SyntaxError("Unexpected tokens at end of expression")
    return float(result)

class _Parser:
    @staticmethod
    def current_token(tokens: Iterator[str]) -> str:
        # This is a helper to peek at the current token if we stored it
        return getattr(_Parser, '_peek', None)

    def __init__(self, tokens: Iterator[str]):
        self.tokens = tokens
        self.current = next(self.tokens, None)

    def _consume(self, expected: str = None):
        token = self.current
        if expected and token != expected:
            raise SyntaxError(f"Expected {expected}, got {token}")
        self.current = next(self.tokens, None)
        return token

    def parse_expression(self) -> float:
        # Lowest precedence: Addition and Subtraction
        node = self.parse_term()
        while self.current in ('+', '-'):
            op = self._consume()
            right = self.parse_term()
            node = node + right if op == '+' else node - right
        return node

    def parse_term(self) -> float:
        # Multiplication and Division
        node = self.parse_unary()
        while self.current in ('*', '/'):
            op = self._consume()
            right = self.parse_unary()
            if op == '/':
                if right == 0: raise ZeroDivisionError("Division by zero")
                node /= right
            else:
                node *= right
        return node

    def parse_unary(self) -> float:
        # Unary minus
        if self.current == '-':
            self._consume()
            return -self.parse_unary()
        return self.parse_exponent()

    def parse_exponent(self) -> float:
        # Right-associative power operator
        node = self.parse_primary()
        if self.current == '**':
            self._consume()
            node = node ** self.parse_unary() # Recurse to unary for right-assoc
        return node

    def parse_primary(self) -> float:
        # Parentheses and Numbers
        token = self._consume()
        if token == '(':
            result = self.parse_expression()
            self._consume(')')
            return result
        try:
            return float(token)
        except (ValueError, TypeError):
            raise SyntaxError(f"Unexpected token: {token}")

