    # Regex captures floats, integers, multi-char operators, and single chars
    pattern = r'\d*\.\d+|\d+| \*\* | [+\-*/()]'
    # Clean whitespace and tokenize
    tokens = re.findall(r'\d*\.\d+|\d+| \*\* |[+\-*/()]', expression, re.VERBOSE)
    # Clean any whitespace that might have leaked into tokens
    return (t.strip() for t in tokens if t.strip())

