def evaluate(expression: str) -> float:
    """Public API: Evaluates an arithmetic expression."""
    tokens = re.findall(r'\d+\.?\d*|\*\*|[+\-*/()]', expression)
    it = iter(tokens)
    curr = next(it, None)

    def consume(expected=None):
        nonlocal curr
        if expected and curr != expected:
            raise EvalError(f"Expected {expected}, got {curr}")
        val = curr
        curr = next(it, None)
        return val

    def parse_atom():
        if curr == '(':
            consume('(')
            res = parse_add()
            consume(')')
            return res
        if curr == '-':
            consume('-')
            return -parse_unary()
        if curr and (curr.isdigit() or '.' in curr):
            return float(consume())
        raise EvalError(f"Unexpected token: {curr}")

    def parse_unary():
        return parse_atom()

    def parse_pow():
        left = parse_unary()
        if curr == '**':
            consume('**')
            return left ** parse_pow()
        return left

    def parse_mul():
        left = parse_pow()
        while curr in ('*', '/'):
            op = consume()
            right = parse_pow()
            left = left * right if op == '*' else left / right
        return left

    def parse_add():
        left = parse_mul()
        while curr in ('+', '-'):
            op = consume()
            right = parse_mul()
            left = left + right if op == '+' else left - right
        return left

    res = parse_add()
    if curr is not None: raise EvalError(f"Trailing garbage: {curr}")
