        """Raises a ParseError with a message."""
        raise ParseError(message)

    def eat(self, token_type: str):
        """Consumes a token of the specified type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.get_next_token()
        else:
            self.error(f"Expected token {token_type}, got {self.current_token.type}")

    def factor(self) -> float:
        """Parses a factor: NUMBER | LPAREN expression RPAREN | unary minus factor."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.expr()
            self.eat('RPAREN')
            return result
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        self.error("Invalid factor")

    def power(self) -> float:
        """Parses a power: factor ('**' factor)*."""
        result = self.factor()
        while self.current_token.type == 'POWER':
            self.eat('POWER')
            result **= self.factor()
        return result

    def term(self) -> float:
        """Parses a term: power (('*' | '/') power)*."""
        result = self.power()
        while self.current_token.type in {'TIMES', 'DIVIDE'}:
            if self.current_token.type == 'TIMES':
                self.eat('TIMES')
                result *= self.power()
            elif self.current_token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.power()
                if divisor == 0:
                    self.error("Division by zero")
                result /= divisor
