import re
from typing import Iterator, Union, Optional

class ExpressionError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Parser:
    """
    Grammar:
    expression   ::= term {('+' | '-') term}
    term         ::= factor {('*' | '/') factor}
    factor       ::= unary ['**' factor]
    unary        ::= '-' unary | primary
    primary      ::= NUMBER | '(' expression ')'
    """

    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.current_token: Optional[str] = None
        self._advance()

    def _tokenize(self, expr: str) -> Iterator[str]:
        # Regex matches numbers (int/float), operators, and parens
        token_pattern = re.compile(r'\d*\.\d+|\d+|[+\-*/()]{1,2}')
        for match in token_pattern.finditer(expr):
            yield match.group()
        yield "EOF"

    def _advance(self) -> None:
        self.current_token = next(self.tokens)

    def _consume(self, expected: str) -> None:
        if self.current_token == expected:
            self._advance()
        else:
            raise ExpressionError(f"Expected '{expected}', got '{self.current_token}'")

    def parse(self) -> float:
        result = self._expression()
        if self.current_token != "EOF":
            raise ExpressionError(f"Unexpected token: {self.current_token}")
        return result

    def _expression(self) -> float:
        node = self._term()
        while self.current_token in ('+', '-'):
            op = self.current_token
            self._advance()
            if op == '+': node += self._term()
            else: node -= self._term()
        return node

    def _term(self) -> float:
        node = self._factor()
        while self.current_token in ('*', '/'):
            op = self.current_token
            self._advance()
            right = self._factor()
            if op == '*': node *= right
            else:
                if right == 0: raise ExpressionError("Division by zero")
                node /= right
        return node

    def _factor(self) -> float:
        node = self._unary()
        if self.current_token == '**':
            self._advance()
            node = node ** self._factor()  # Right-associative
        return node

    def _unary(self) -> float:
        if self.current_token == '-':
            self._advance()
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        token = self.current_token
        if token is None or token == "EOF":
            raise ExpressionError("Unexpected end of expression")

        if token == '(':
            self._advance()
            result = self._expression()
            self._consume(')')
            return result

        try:
            val = float(token)
            self._advance()
            return val
        except ValueError:
            raise ExpressionError(f"Invalid number or syntax: {token}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression string.
    """
    if not expression or not expression.strip():
        raise ExpressionError("Empty expression")
    return Parser(expression).parse()

