from typing import List, Tuple, Union

# Token types
NUMBER = "NUMBER"
PLUS = "PLUS"
MINUS = "MINUS"
TIMES = "TIMES"
DIVIDE = "DIVIDE"
POWER = "POWER"
LPAREN = "LPAREN"
RPAREN = "RPAREN"
END = "END"

Token = Tuple[str, Union[float, str]]  # (type, value) – value is float for NUMBER, otherwise the operator char

def tokenize(s: str) -> List[Token]:
    """Convert expression string to a list of tokens."""
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit() or ch == '.':
            start = i
            while i < n and (s[i].isdigit() or s[i] == '.'):
                i += 1
            num_str = s[start:i]
            if num_str.count('.') > 1:
                raise ValueError(f"Invalid number format: '{num_str}'")
            try:
                value = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: '{num_str}'")
            tokens.append((NUMBER, value))
            continue
        if ch == '+':
            tokens.append((PLUS, ch))
        elif ch == '-':
            tokens.append((MINUS, ch))
        elif ch == '*':
            # check for **
            if i + 1 < n and s[i+1] == '*':
                tokens.append((POWER, '**'))
                i += 2
                continue
            else:
                tokens.append((TIMES, ch))
        elif ch == '/':
            tokens.append((DIVIDE, ch))
        elif ch == '(':
            tokens.append((LPAREN, ch))
        elif ch == ')':
            tokens.append((RPAREN, ch))
        else:
            raise ValueError(f"Unexpected character: '{ch}' at position {i}")
        i += 1
    tokens.append((END, ''))
    return tokens


class Parser:
    """Recursive-descent parser that evaluates the expression."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: str) -> Token:
        tok = self.peek()
        if tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]} ('{tok[1]}')")
        self.pos += 1
        return tok

    def parse_expression(self) -> float:
        """Parse highest level: + and - (left-associative)."""
        left = self.parse_term()
        while self.peek()[0] in (PLUS, MINUS):
            op = self.consume(self.peek()[0])[0]
            right = self.parse_term()
            if op == PLUS:
                left += right
            else:
                left -= right
        return left

    def parse_term(self) -> float:
        """Parse * and / (left-associative)."""
        left = self.parse_unary()
        while self.peek()[0] in (TIMES, DIVIDE):
            op = self.consume(self.peek()[0])[0]
            right = self.parse_unary()
            if op == TIMES:
                left *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                left /= right
        return left

    def parse_unary(self) -> float:
        """Handle unary minus (higher precedence than * /, lower than **)."""
        if self.peek()[0] == MINUS:
            self.consume(MINUS)
            # recursive unary allows --x
            return -self.parse_unary()
        return self.parse_factor()

    def parse_factor(self) -> float:
        """Primary numbers/parentheses, then optional right-associative **."""
        tok = self.peek()
        if tok[0] == NUMBER:
            self.consume(NUMBER)
            base = tok[1]  # float
        elif tok[0] == LPAREN:
            self.consume(LPAREN)
            base = self.parse_expression()
            if self.peek()[0] != RPAREN:
                raise ValueError("Missing closing parenthesis")
            self.consume(RPAREN)
        else:
            raise ValueError(f"Unexpected token: {tok[0]} ('{tok[1]}')")

        # Handle exponentiation (right-associative)
        if self.peek()[0] == POWER:
            self.consume(POWER)
            exponent = self.parse_factor()  # right recursion gives right-associativity
            base **= exponent
        return base


