    tokens = tokenize(expression)
    parser = Parser(tokens)
    result = parser.parse_expression()
    # Ensure we consumed all tokens (except END)
    if parser.peek()[0] != END:
        raise ValueError(f"Unexpected trailing tokens")
    return result


