                if self.current_char == '.':
                    next_pos = self.pos + 1
                    if next_pos >= len(self.text) or not self.text[next_pos].isdigit():
                        self.error("Invalid number: decimal point without digits")
                return Token(TokenType.NUMBER, self.read_number(), self.pos)

            if self.current_char == '+':
                token = Token(TokenType.PLUS, '+', self.pos)
                self.advance()
                return token

            if self.current_char == '-':
                token = Token(TokenType.MINUS, '-', self.pos)
                self.advance()
                return token

            if self.current_char == '*':
                self.advance()
                if self.current_char == '*':
                    token = Token(TokenType.POW, '**', self.pos - 1)
                    self.advance()
                    return token
                return Token(TokenType.STAR, '*', self.pos - 1)

            if self.current_char == '/':
                token = Token(TokenType.SLASH, '/', self.pos)
                self.advance()
                return token

            if self.current_char == '(':
                token = Token(TokenType.LPAREN, '(', self.pos)
                self.advance()
                return token

            if self.current_char == ')':
                token = Token(TokenType.RPAREN, ')', self.pos)
                self.advance()
                return token

            self.error(f"Unexpected character: '{self.current_char}'")

        return Token(TokenType.EOF, None, self.pos)

# Parser
class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, message: str):
        raise ParserError(f"{message} at position {self.current_token.pos}", self.current_token.pos)

    def eat(self, token_type: TokenType):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error(f"Expected {token_type}, got {self.current_token.type}")

    # Grammar:
    # expression -> term (('+' | '-') term)*
    # term -> factor (('*' | '/') factor)*
    # factor -> unary | power
    # unary -> ('-') unary | power
    # power -> primary ('**' factor)*  # Right-associative
    # primary -> NUMBER | '(' expression ')'

    def expression(self) -> ASTNode:
        node = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            operator = self.current_token.value
            self.eat(self.current_token.type)
            right = self.term()
            node = BinOpNode(operator, node, right)

        return node

    def term(self) -> ASTNode:
        node = self.factor()

        while self.current_token.type in (TokenType.STAR, TokenType.SLASH):
            operator = self.current_token.value
            self.eat(self.current_token.type)
            right = self.factor()
            node = BinOpNode(operator, node, right)

        return node

    def factor(self) -> ASTNode:
        # Factor can be unary or power
        if self.current_token.type == TokenType.MINUS:
            return self.unary()
        return self.power()

    def unary(self) -> ASTNode:
        # Unary minus has higher precedence than **
        if self.current_token.type == TokenType.MINUS:
            self.eat(TokenType.MINUS)
            operand = self.unary()  # Unary is right-associative
            return UnaryOpNode('-', operand)
        return self.power()

    def power(self) -> ASTNode:
        # Power is right-associative: primary ** factor
        node = self.primary()

        if self.current_token.type == TokenType.POW:
            self.eat(TokenType.POW)
            right = self.factor()  # Right operand is factor (allows unary)
            node = BinOpNode('**', node, right)

        return node

    def primary(self) -> ASTNode:
        token = self.current_token

        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return NumberNode(token.value)

        if token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            node = self.expression()
            if self.current_token.type != TokenType.RPAREN:
                self.error("Expected ')'")
            self.eat(TokenType.RPAREN)
            return node

        self.error(f"Unexpected token: {token.type}")

# Evaluator
class Evaluator:
    def visit(self, node: ASTNode) -> float:
        if isinstance(node, NumberNode):
            return node.value
        elif isinstance(node, UnaryOpNode):
            operand = self.visit(node.operand)
            if node.operator == '-':
                return -operand
        elif isinstance(node, BinOpNode):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if node.operator == '+':
                return left + right
            elif node.operator == '-':
                return left - right
            elif node.operator == '*':
                return left * right
            elif node.operator == '/':
                if right == 0:
                    raise ParserError("Division by zero", -1)
                return left / right
            elif node.operator == '**':
                return left ** right
        raise ValueError(f"Unknown node type: {type(node)}")

# Public API
def evaluate(expression: str) -> float:
    """
    Evaluate an arithmetic expression and return the result as a float.

    Args:
        expression: A string containing an arithmetic expression.

    Returns:
        The result of the expression as a float.

    Raises:
        ParserError: If the expression is malformed.
    """
    lexer = Lexer(expression)
    parser = Parser(lexer)
    ast = parser.expression()

    if parser.current_token.type != TokenType.EOF:
        parser.error("Unexpected token after expression")

    evaluator = Evaluator()
    return evaluator.visit(ast)

# Usage examples
if __name__ == "__main__":
    # Example 1: Precedence and right-associativity of **
    # 2 ** 3 ** 2 should be 2 ** (3 ** 2) = 2 ** 9 = 512
    result = evaluate("2 ** 3 ** 2")
    print(f"2 ** 3 ** 2 = {result}")  # Expected: 512.0

    # Example 2: Parentheses and unary minus
    # -(3 + 2) = -5
