    print(f"-(3 + 2) = {result}")  # Expected: -5.0

    # Example 3: Combined operators with precedence
    # 2 + 3 * 4 ** 2 - 10 / 2 = 2 + 3 * 16 - 5 = 2 + 48 - 5 = 45
    result = evaluate("2 + 3 * 4 ** 2 - 10 / 2")
    print(f"2 + 3 * 4 ** 2 - 10 / 2 = {result}")  # Expected: 45.0

    # Additional examples to test unary minus with **
    # -3 ** 2 = -(3 ** 2) = -9 (unary minus has lower precedence than **)
    result = evaluate("-3 ** 2")
    print(f"-3 ** 2 = {result}")  # Expected: -9.0

    # 2 ** -3 = 2 ** (-3) = 0.125 (unary minus in exponent)
