from typing import List, Union, Optional
import math

class Token:
    """Represents a token in the expression"""
    def __init__(self, type: str, value: Union[str, float, int, None] = None):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value})"

class ParserError(Exception):
    """Custom exception for parser errors"""
    pass

class ArithmeticEvaluator:
    """Recursive-descent parser and evaluator for arithmetic expressions"""

    def __init__(self):
        self.tokens: List[Token] = []
        self.pos: int = 0
        self.current_token: Optional[Token] = None

    def tokenize(self, expression: str) -> List[Token]:
        """Convert input string into a stream of tokens"""
        tokens = []
        i = 0
        n = len(expression)

        while i < n:
            char = expression[i]

            # Skip whitespace
            if char.isspace():
                i += 1
                continue

            # Numbers (integers and floats)
            if char.isdigit() or char == '.':
                num_str = ''
                has_decimal = False

                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    if expression[i] == '.':
                        if has_decimal:
                            raise ParserError("Invalid number with multiple decimal points")
                        has_decimal = True
                    num_str += expression[i]
                    i += 1

                # Check if it's a valid number
                if num_str == '.':
                    raise ParserError("Invalid number format")

                # Convert to appropriate numeric type
                if has_decimal:
                    tokens.append(Token('NUMBER', float(num_str)))
                else:
                    tokens.append(Token('NUMBER', int(num_str)))
                continue

            # Operators and parentheses
            if char in '+-*/()':
                if char == '-':
                    # Check if it's unary minus
                    if not tokens or (tokens[-1].type not in ['NUMBER', 'RPAREN']):
                        tokens.append(Token('UNARY_MINUS'))
                    else:
                        tokens.append(Token('OPERATOR', char))
                elif char == '+':
                    # Check if it's unary plus (just ignore it)
                    if not tokens or (tokens[-1].type not in ['NUMBER', 'RPAREN']):
                        # Unary plus, skip it
                        pass
                    else:
                        tokens.append(Token('OPERATOR', char))
                else:
                    tokens.append(Token('OPERATOR', char))
                i += 1
                continue

            # Exponentiation operator
            if char == '*':
                if i + 1 < n and expression[i + 1] == '*':
                    tokens.append(Token('OPERATOR', '**'))
                    i += 2
                else:
                    tokens.append(Token('OPERATOR', '*'))
                    i += 1
                continue

            # Invalid character
            raise ParserError(f"Unexpected character: '{char}'")

        return tokens

    def advance(self) -> None:
        """Move to the next token"""
        self.pos += 1
        if self.pos < len(self.tokens):
            self.current_token = self.tokens[self.pos]
        else:
            self.current_token = None

    def eat(self, token_type: str, value: Optional[str] = None) -> None:
        """Consume a token if it matches the expected type and value"""
        if self.current_token is None:
            raise ParserError(f"Expected {token_type}, got end of input")

        if self.current_token.type != token_type:
            raise ParserError(f"Expected {token_type}, got {self.current_token.type}")

        if value is not None and self.current_token.value != value:
            raise ParserError(f"Expected {value}, got {self.current_token.value}")

        self.advance()

    def parse_expression(self) -> float:
        """Parse and evaluate an expression"""
        result = self.parse_term()

        while self.current_token and self.current_token.type == 'OPERATOR' and self.current_token.value in ('+', '-'):
            op = self.current_token.value
            self.advance()
            right = self.parse_term()

            if op == '+':
                result += right
            else:
                result -= right

        return result

    def parse_term(self) -> float:
        """Parse and evaluate a term"""
        result = self.parse_factor()

        while self.current_token and self.current_token.type == 'OPERATOR' and self.current_token.value in ('*', '/'):
            op = self.current_token.value
            self.advance()
            right = self.parse_factor()

            if op == '*':
                result *= right
            elif op == '/':
                if right == 0:
                    raise ParserError("Division by zero")
                result /= right

        return result

    def parse_factor(self) -> float:
        """Parse and evaluate a factor (handles exponentiation)"""
        result = self.parse_unary()

        while self.current_token and self.current_token.type == 'OPERATOR' and self.current_token.value == '**':
            self.advance()
            right = self.parse_unary()  # Right-associative: parse unary for right operand
            result = math.pow(result, right)

        return result

    def parse_unary(self) -> float:
        """Parse and evaluate unary operators"""
        if self.current_token and self.current_token.type == 'UNARY_MINUS':
            self.advance()
            return -self.parse_atom()

        return self.parse_atom()

    def parse_atom(self) -> float:
        """Parse and evaluate an atom (number or parenthesized expression)"""
        if self.current_token is None:
            raise ParserError("Unexpected end of input")

        if self.current_token.type == 'NUMBER':
            value = float(self.current_token.value)
            self.advance()
            return value

        if self.current_token.type == 'OPERATOR' and self.current_token.value == '(':
            self.advance()
            result = self.parse_expression()

            if self.current_token is None or not (self.current_token.type == 'OPERATOR' and self.current_token.value == ')'):
                raise ParserError("Unbalanced parentheses")

            self.advance()
            return result

        raise ParserError(f"Unexpected token: {self.current_token}")

    def evaluate(self, expression: str) -> float:
        """Public API: Evaluate an arithmetic expression"""
        # Reset parser state
        self.tokens = self.tokenize(expression)
        self.pos = 0
        self.current_token = self.tokens[0] if self.tokens else None

        if not self.tokens:
            raise ParserError("Empty expression")

        result = self.parse_expression()

        # Check if we consumed all tokens
        if self.current_token is not None:
            raise ParserError(f"Unexpected token at end: {self.current_token}")

        return result


# Usage examples
def main():
    evaluator = ArithmeticEvaluator()

    # Example 1: Basic precedence
    print("Example 1: Basic precedence")
    expr1 = "2 + 3 * 4 ** 2"
    result1 = evaluator.evaluate(expr1)
    print(f"{expr1} = {result1}")  # 2 + 3 * 16 = 2 + 48 = 50

    # Example 2: Parentheses and unary minus
    print("\nExample 2: Parentheses and unary minus")
    expr2 = "-(3 + 4) * 2 - -5"
    result2 = evaluator.evaluate(expr2)
    print(f"{expr2} = {result2}")  # -7 * 2 - -5 = -14 + 5 = -9

    # Example 3: Complex expression with all operators
    print("\nExample 3: Complex expression")
    expr3 = "2 ** 3 ** 2 / (4 + 1) - -3.5"
    result3 = evaluator.evaluate(expr3)
    print(f"{expr3} = {result3}")  # 2 ** 9 / 5 + 3.5 = 512 / 5 + 3.5 = 102.4 + 3.5 = 105.9

    # Example 4: Division by zero (error handling)
    print("\nExample 4: Error handling - division by zero")
    try:
        expr4 = "5 / 0"
        result4 = evaluator.evaluate(expr4)
        print(f"{expr4} = {result4}")
    except ParserError as e:
        print(f"Error: {e}")

    # Example 5: Unbalanced parentheses (error handling)
    print("\nExample 5: Error handling - unbalanced parentheses")
    try:
        expr5 = "(2 + 3 * (4 - 1)"
        result5 = evaluator.evaluate(expr5)
        print(f"{expr5} = {result5}")
    except ParserError as e:
        print(f"Error: {e}")


if __name__ == "__main__":
    main()

