expression  → term (('+' | '-') term)*
term        → factor (('*' | '/') factor)*
factor      → unary ('**' unary)*
unary       → '-' unary | atom
atom        → NUMBER | '(' expression ')'

from typing import Union, List, Tuple
import re

class ParseError(Exception):
    """Raised when the input cannot be parsed"""
    pass

class EvalError(Exception):
    """Raised when evaluation fails (e.g., division by zero)"""
    pass

Token = Union[float, str]  # Tokens are either numbers or operators/parentheses

class ArithmeticEvaluator:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        """Return the current token without consuming it"""
        if self.pos >= len(self.tokens):
            return None
        return self.tokens[self.pos]

    def consume(self) -> Token:
        """Consume and return the current token"""
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")
        self.pos += 1
        return token

    def expect(self, expected: str) -> Token:
        """Consume and return the current token if it matches expected"""
        token = self.peek()
        if token != expected:
            raise ParseError(f"Expected '{expected}', got '{token}'")
        return self.consume()

    def parse_expression(self) -> float:
        """Parse an expression (handles + and -)"""
        left = self.parse_term()
        while True:
            op = self.peek()
            if op in ('+', '-'):
                self.consume()
                right = self.parse_term()
                if op == '+':
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def parse_term(self) -> float:
        """Parse a term (handles * and /)"""
        left = self.parse_factor()
        while True:
            op = self.peek()
            if op in ('*', '/'):
                self.consume()
                right = self.parse_factor()
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise EvalError("Division by zero")
                    left /= right
            else:
                break
        return left

    def parse_factor(self) -> float:
        """Parse a factor (handles ** and unary minus)"""
        left = self.parse_exponent()
        while True:
            op = self.peek()
            if op == '**':
                self.consume()
                right = self.parse_exponent()
                left **= right
            else:
                break
        return left

    def parse_exponent(self) -> float:
        """Parse an exponent (handles unary minus)"""
        token = self.peek()
        if token == '-':
            self.consume()
            value = self.parse_exponent()
            return -value
        elif token == '+':
            self.consume()
            return self.parse_exponent()
        else:
            return self.parse_primary()

    def parse_primary(self) -> float:
        """Parse a primary (numbers or parenthesized expressions)"""
        token = self.peek()
        if isinstance(token, (int, float)):
            return self.consume()
        elif token == '(':
            self.consume()
            value = self.parse_expression()
            self.expect(')')
            return value
        else:
            raise ParseError(f"Unexpected token: '{token}'")

def tokenize(expression: str) -> List[Token]:
    """Convert a string expression into a list of tokens"""
    # Regular expression to match numbers, operators, and parentheses
    token_pattern = re.compile(r"""
        \s*  # Skip whitespace
        (?:
            (?P<number>-?\d+\.?\d*|\.\d+)  # Numbers (int or float)
            |(?P<operator>[+\-*/()])  # Operators and parentheses
            |(?P<exponent>\*\*)  # Exponent operator
        )
    """, re.VERBOSE)

    tokens = []
    for match in token_pattern.finditer(expression):
        if match.lastgroup == 'number':
            try:
                # Try to parse as int first, then float
                num = int(match.group('number'))
            except ValueError:
                num = float(match.group('number'))
            tokens.append(num)
        elif match.lastgroup == 'operator':
            tokens.append(match.group('operator'))
        elif match.lastgroup == 'exponent':
            tokens.append('**')

    # Check for invalid characters
    if not token_pattern.fullmatch(expression.replace(' ', '')):
        invalid = set(expression.replace(' ', '')) - set('+-*/().0123456789')
        if invalid:
            raise ParseError(f"Invalid characters in expression: {invalid}")

    return tokens

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result as a float"""
    tokens = tokenize(expression)
    if not tokens:
        raise ParseError("Empty expression")

    evaluator = ArithmeticEvaluator(tokens)
    try:
        result = evaluator.parse_expression()
    except IndexError:
        raise ParseError("Unexpected end of input")

    # Check if we consumed all tokens
    if evaluator.pos < len(tokens):
        raise ParseError(f"Unexpected token after expression: '{tokens[evaluator.pos]}'")

    return float(result)

# --- file boundary ---

# Example 1: Operator precedence
print(evaluate("2 + 3 * 4"))  # 2 + (3 * 4) = 14
print(evaluate("2 * 3 + 4"))  # (2 * 3) + 4 = 10
print(evaluate("2 ** 3 + 4"))  # (2 ** 3) + 4 = 12

# Example 2: Parentheses for grouping
print(evaluate("(2 + 3) * 4"))  # (2 + 3) * 4 = 20
print(evaluate("2 * (3 + 4)"))  # 2 * (3 + 4) = 14
print(evaluate("2 ** (3 + 1)"))  # 2 ** (3 + 1) = 16

# Example 3: Unary minus
print(evaluate("-2 + 3"))  # (-2) + 3 = 1
print(evaluate("2 * -3"))  # 2 * (-3) = -6
print(evaluate("-(-2 + 3)"))  # -((-2) + 3) = -1
print(evaluate("2 ** -3"))  # 2 ** (-3) = 0.125

# Example 4: Error cases
try:
    evaluate("2 + * 3")  # Syntax error
except ParseError as e:
    print(f"Error: {e}")

try:
    evaluate("2 / 0")  # Division by zero
except EvalError as e:
    print(f"Error: {e}")

try:
    evaluate("2 + (3 * 4")  # Unbalanced parentheses
except ParseError as e:
    print(f"Error: {e}")

try:
    evaluate("2 + $ 3")  # Invalid character
except ParseError as e:
    print(f"Error: {e}")

import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """A class representing a token."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

class Tokenizer:
    """A tokenizer for arithmetic expressions."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def advance(self):
        """Advance the current character position."""
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        """Skip whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> Token:
        """Return a number token (integer or float)."""
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return Token('NUMBER', float(num_str))

    def get_next_token(self) -> Token:
        """Return the next token from the input expression."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token('PLUS', '+')
            if self.current_char == '-':
                self.advance()
                return Token('MINUS', '-')
            if self.current_char == '*':
                self.advance()
                return Token('MUL', '*')
            if self.current_char == '/':
                self.advance()
                return Token('DIV', '/')
            if self.current_char == '**':
                self.advance()
                return Token('POW', '**')
            if self.current_char == '(':
                self.advance()
                return Token('LPAREN', '(')
            if self.current_char == ')':
                self.advance()
                return Token('RPAREN', ')')
            raise ParseError(f'Unexpected character: {self.current_char}')
        return Token('EOF', None)

class ASTNode:
    """Base class for AST nodes."""
    pass

class BinOp(ASTNode):
    """Binary operation node."""
    def __init__(self, left: ASTNode, op: Token, right: ASTNode):
        self.left = left
        self.op = op
        self.right = right

class UnaryOp(ASTNode):
    """Unary operation node."""
    def __init__(self, op: Token, expr: ASTNode):
        self.op = op
        self.expr = expr

class Num(ASTNode):
    """Number node."""
    def __init__(self, token: Token):
        self.token = token

class Parser:
    """A parser for arithmetic expressions."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.get_next_token()

    def error(self):
        """Raise a parsing error."""
        raise ParseError(f'Invalid syntax at token: {self.current_token}')

    def eat(self, token_type: str):
        """Consume a token of the specified type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.get_next_token()
        else:
            self.error()

    def factor(self) -> ASTNode:
        """Parse a factor (number or unary operation)."""
        token = self.current_token
        if token.type == 'MINUS':
            self.eat('MINUS')
            return UnaryOp(token, self.factor())
        elif token.type == 'NUMBER':
            self.eat('NUMBER')
            return Num(token)
        elif token.type == 'LPAREN':
            self.eat('LPAREN')
            node = self.expr()
            self.eat('RPAREN')
            return node
        self.error()

    def term(self) -> ASTNode:
        """Parse a term (factor followed by * or /)."""
        node = self.factor()
        while self.current_token.type in ('MUL', 'DIV'):
            token = self.current_token
            if token.type == 'MUL':
                self.eat('MUL')
            elif token.type == 'DIV':
                self.eat('DIV')
            node = BinOp(node, token, self.factor())
        return node

    def power(self) -> ASTNode:
        """Parse a power operation (factor followed by **)."""
        node = self.term()
        while self.current_token.type == 'POW':
            token = self.current_token
            self.eat('POW')
            node = BinOp(node, token, self.term())
        return node

    def expr(self) -> ASTNode:
        """Parse an expression (term followed by + or -)."""
        node = self.power()
        while self.current_token.type in ('PLUS', 'MINUS'):
            token = self.current_token
            if token.type == 'PLUS':
                self.eat('PLUS')
            elif token.type == 'MINUS':
                self.eat('MINUS')
            node = BinOp(node, token, self.power())
        return node

    def parse(self) -> ASTNode:
        """Parse the entire expression."""
        node = self.expr()
        if self.current_token.type != 'EOF':
            self.error()
        return node

class Evaluator:
    """An evaluator for the AST."""
    def visit(self, node: ASTNode) -> float:
        """Visit a node and return its value."""
        if isinstance(node, Num):
            return node.token.value
        elif isinstance(node, BinOp):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if node.op.type == 'PLUS':
                return left + right
            elif node.op.type == 'MINUS':
                return left - right
            elif node.op.type == 'MUL':
                return left * right
            elif node.op.type == 'DIV':
                if right == 0:
                    raise ZeroDivisionError("Division by zero.")
                return left / right
        elif isinstance(node, UnaryOp):
            return -self.visit(node.expr)
        raise ParseError("Invalid AST node.")

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    ast = parser.parse()
    evaluator = Evaluator()
    return evaluator.visit(ast)

# Usage examples
if __name__ == "__main__":
    try:
        print(evaluate("3 + 5 * 2"))  # 13.0
        print(evaluate("(3 + 5) * 2"))  # 16.0
        print(evaluate("-3 + 5"))  # 2.0
        print(evaluate("2 ** 3 ** 2"))  # 512.0
        print(evaluate("10 / (2 - 2)"))  # Raises ZeroDivisionError
    except Exception as e:
        print(f"Error: {e}")

import re
from typing import List, Union

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Parser:
    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expr: str) -> List[str]:
        # Tokenize numbers, operators, and parentheses
        token_pattern = re.compile(r'\d*\.\d+|\d+|[+\-*/()^]')
        tokens = token_pattern.findall(expr.replace('**', '^'))
        # Validate for unexpected characters
        if len("".join(tokens)) != len(expr.replace(" ", "")):
            raise ParseError("Input contains invalid characters")
        return tokens

    def _peek(self) -> Union[str, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self) -> str:
        token = self._peek()
        self.pos += 1
        return token

    def parse_expression(self) -> float:
        """Entry point: handles + and -"""
        node = self.parse_term()
        while self._peek() in ('+', '-'):
            op = self._consume()
            right = self.parse_term()
            node = (node + right) if op == '+' else (node - right)
        return node

    def parse_term(self) -> float:
        """Handles * and /"""
        node = self.parse_unary()
        while self._peek() in ('*', '/'):
            op = self._consume()
            right = self.parse_unary()
            if op == '*':
                node *= right
            else:
                if right == 0: raise ParseError("Division by zero")
                node /= right
        return node

    def parse_unary(self) -> float:
        """Handles unary minus"""
        if self._peek() == '-':
            self._consume()
            return -self.parse_unary()
        return self.parse_exponent()

    def parse_exponent(self) -> float:
        """Handles ** (right-associative)"""
        node = self.parse_factor()
        if self._peek() == '^':
            self._consume()
            node = node ** self.parse_exponent()
        return node

    def parse_factor(self) -> float:
        """Handles numbers and parentheses"""
        token = self._consume()
        if token == '(':
            result = self.parse_expression()
            if self._consume() != ')':
                raise ParseError("Unbalanced parentheses")
            return result
        try:
            return float(token)
        except (TypeError, ValueError):
            raise ParseError(f"Unexpected token: {token}")

def evaluate(expression: str) -> float:
    """Public API to evaluate arithmetic expressions."""
    parser = Parser(expression)
    result = parser.parse_expression()
    if parser.pos < len(parser.tokens):
        raise ParseError("Trailing data in expression")
    return float(result)

# --- Usage Examples ---
if __name__ == "__main__":
    # 1. Precedence: * before +
    print(f"1 + 2 * 3 = {evaluate('1 + 2 * 3')}")  # 7.0

    # 2. Parentheses and Unary Minus
    print(f"-(2 + 3) * 4 = {evaluate('-(2 + 3) * 4')}")  # -20.0

    # 3. Exponentiation (Right-associativity: 2**3**2 = 2**9 = 512)
    print(f"2 ** 3 ** 2 = {evaluate('2 ** 3 ** 2')}")  # 512.0

